package blockbranch.realistic;
import java.util.*;
public class MontaneMeadowCheck{
 public static void main(String[]args){for(long seed:new long[]{424242,1,-17}){var d=new DrainageNetwork(new TerrainShape(seed),seed);var c=new ClimateField(seed);var ecology=new GroundEcology.Field(d::sample,c);int before=0,chosen=0;for(int z=-1900000;z<=1900000;z+=16000)for(int x=-1900000;x<=1900000;x+=16000){boolean old=LowlandMeadow.contains(x,z,d,c)&&!OakBirchWoodland.potential(seed,x,z,d,c)&&!WarmWoodland.contains(seed,x,z,d,c)&&!HumidWoodland.contains(seed,x,z,d,c);if(old)before++;if(!MontaneMeadow.contains(seed,x,z,d,c))continue;chosen++;require(old&&!LandVegetation.reserved(d,x,z)&&!Plains.contains(seed,x,z,d,c)&&!Swamp.soilContains(seed,x,z,d,c)&&MontaneTerrain.relief(d,x,z)>=180,"Only prior open soil-supported meadow in actual mountain context");}require(chosen>100&&chosen<before*.15,"Meaningful mountain grassland and substantial retained specific meadow");var p=blockbranch.realistic.MontaneMeadowFixtures.fixture(d,seed);int[] codes=new int[14];int edges=0,near=0,total=0;var phaseX=new int[16];for(int z=p.z()-96;z<p.z()+96;z++)for(int x=p.x()-96;x<p.x()+96;x++){var site=ecology.sample(x,z);int code=MontaneMeadow.cover(seed,x,z,site,true);codes[code]++;if(code>=11||code>=4&&code<=6){total++;phaseX[Math.floorMod(x,16)]++;int next=MontaneMeadow.cover(seed,x+8,z,ecology.sample(x+8,z),true);if(next>=11||next>=4&&next<=6)near++;}if(code!=MontaneMeadow.cover(seed,x,z,site,true))throw new AssertionError("Unseeded flower cover");}for(int code:new int[]{4,5,6,7,8,11,12,13})require(codes[code]>0,"Native meadow palette component "+code);double density=total/(192.*192),neighbour=near/(double)total,mean=total/16.;double variance=0;for(int n:phaseX)variance+=(n-mean)*(n-mean);double cv=Math.sqrt(variance/16)/mean;require(neighbour>density*1.2&&cv<.15,"Colony-scale clustering survives local stem competition without coordinate-phase rows");System.out.println("MONTANE_MEADOW seed="+seed+" selected="+chosen+" retained="+(before-chosen)+" before="+before+" point="+p+" cover="+Arrays.toString(codes)+" flowerDensity="+density+" neighbour="+neighbour+" phaseCV="+cv);}
 System.out.println("MONTANE_MEADOW_RETAINED_PARTITION_FLOWER_COLONIES_SUPPORT_ORDER_PASS");}
 static void require(boolean b,String m){if(!b)throw new AssertionError(m);}
}
